-- TTNAVA: Phố tiếng Trung, MySQL/MariaDB local only.
-- Create missing tables and insert missing lesson content; never overwrite teacher edits.
-- No student accounts, grades, recordings or API keys in this file.
SET NAMES utf8mb4;
USE kids_learning;

CREATE TABLE IF NOT EXISTS chinese_street_lessons (
 lesson_id CHAR(36) PRIMARY KEY,
 data JSON NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(lesson_id) REFERENCES chinese_lessons(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chinese_street_progress (
 student_id CHAR(36) NOT NULL,lesson_id CHAR(36) NOT NULL,
 mission_id VARCHAR(50) NOT NULL,content_hash CHAR(64) NOT NULL,
 wrong_count INT UNSIGNED NOT NULL DEFAULT 0,best_stars TINYINT UNSIGNED NOT NULL DEFAULT 0,
 last_request CHAR(36) NULL,last_choice VARCHAR(50) NULL,last_response JSON NULL,
 completed_at DATETIME(3) NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY(student_id,lesson_id,mission_id,content_hash),
 INDEX street_recent(updated_at),
 FOREIGN KEY(student_id) REFERENCES profiles(id) ON DELETE CASCADE,
 FOREIGN KEY(lesson_id) REFERENCES chinese_lessons(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
-- Bài 1 . Xin Chào
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT '5e27a6ad-005f-42e8-8d5c-a735f3ecd7a9','{\"enabled\":true,\"place_id\":\"school\",\"missions\":[{\"id\":\"greeting\",\"title\":\"Lời chào đầu ngày\",\"instruction\":\"Nghe lời chào và chọn câu đáp phù hợp.\",\"speech\":\"你好！\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"谢谢！\"},{\"id\":\"c2\",\"label\":\"你好！\"},{\"id\":\"c3\",\"label\":\"再见！\"}],\"answer\":\"c2\",\"feedback\":\"你好！ là lời chào; con có thể đáp lại bằng 你好！\"},{\"id\":\"wellbeing\",\"title\":\"Hôm nay bạn khỏe không?\",\"instruction\":\"Nghe câu hỏi và chọn câu trả lời đúng ý.\",\"speech\":\"你好吗？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我很好，谢谢！\"},{\"id\":\"c2\",\"label\":\"再见！\"},{\"id\":\"c3\",\"label\":\"不客气！\"}],\"answer\":\"c1\",\"feedback\":\"你好吗？ hỏi thăm sức khỏe. 我很好，谢谢！ nghĩa là “Mình khỏe, cảm ơn!”.\"},{\"id\":\"goodbye\",\"title\":\"Hẹn gặp lại\",\"instruction\":\"Nghe rồi chọn lời đáp khi chia tay.\",\"speech\":\"再见！\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"你好！\"},{\"id\":\"c2\",\"label\":\"谢谢！\"},{\"id\":\"c3\",\"label\":\"再见！\"}],\"answer\":\"c3\",\"feedback\":\"再见！ dùng khi chào tạm biệt. Đáp lại bằng 再见！ nhé.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='5e27a6ad-005f-42e8-8d5c-a735f3ecd7a9');

-- Bài 2 . Hỏi tên, Hỏi họ, Quốc tịch,
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT 'd85a9dcc-4f4e-4401-8310-610f6213204d','{\"enabled\":true,\"place_id\":\"school\",\"missions\":[{\"id\":\"name\",\"title\":\"Người bạn mới\",\"instruction\":\"Nghe câu hỏi rồi chọn lời giới thiệu tên.\",\"speech\":\"你叫什么名字？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我是学生。\"},{\"id\":\"c2\",\"label\":\"我叫小安。\"},{\"id\":\"c3\",\"label\":\"我很好。\"}],\"answer\":\"c2\",\"feedback\":\"你叫什么名字？ hỏi tên. 我叫小安。 nghĩa là “Mình tên là Tiểu An”.\"},{\"id\":\"country\",\"title\":\"Thẻ quốc tịch\",\"instruction\":\"Nghe bạn giới thiệu và chọn quốc tịch của bạn ấy.\",\"speech\":\"你好，我叫小明。我是越南人。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"中国人\"},{\"id\":\"c2\",\"label\":\"美国人\"},{\"id\":\"c3\",\"label\":\"越南人\"}],\"answer\":\"c3\",\"feedback\":\"Bạn ấy nói 我是越南人。 nghĩa là “Mình là người Việt Nam”.\"},{\"id\":\"surname\",\"title\":\"Bạn họ gì?\",\"instruction\":\"Chọn câu trả lời phù hợp với câu vừa nghe.\",\"speech\":\"你姓什么？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我姓王。\"},{\"id\":\"c2\",\"label\":\"我去学校。\"},{\"id\":\"c3\",\"label\":\"我喝水。\"}],\"answer\":\"c1\",\"feedback\":\"姓 dùng khi hỏi họ. 我姓王。 nghĩa là “Mình họ Vương”.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='d85a9dcc-4f4e-4401-8310-610f6213204d');

-- Bài 3. 很高兴认识你 — Rất vui được làm quen với bạn
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT '7597944b-9946-4e42-9a10-234a0065fd9d','{\"enabled\":true,\"place_id\":\"school\",\"missions\":[{\"id\":\"meeting\",\"title\":\"Rất vui được gặp bạn\",\"instruction\":\"Nghe rồi chọn lời đáp tự nhiên.\",\"speech\":\"很高兴认识你！\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我也很高兴。\"},{\"id\":\"c2\",\"label\":\"我去银行。\"},{\"id\":\"c3\",\"label\":\"我吃面条。\"}],\"answer\":\"c1\",\"feedback\":\"我也很高兴。 là cách đáp “Mình cũng rất vui”.\"},{\"id\":\"teacher\",\"title\":\"Gặp cô giáo\",\"instruction\":\"Nghe lời giới thiệu và nhận biết nghề nghiệp.\",\"speech\":\"这是王老师。她是我们的汉语老师。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"学生\"},{\"id\":\"c2\",\"label\":\"老师\"},{\"id\":\"c3\",\"label\":\"医生\"}],\"answer\":\"c2\",\"feedback\":\"老师 nghĩa là giáo viên. 她是我们的汉语老师。: “Cô ấy là giáo viên tiếng Trung của chúng mình”.\"},{\"id\":\"card\",\"title\":\"Tấm danh thiếp\",\"instruction\":\"Nghe rồi chọn chủ nhân của tấm danh thiếp.\",\"speech\":\"这是谁的名片？这是李老师的名片。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"王老师\"},{\"id\":\"c2\",\"label\":\"小安\"},{\"id\":\"c3\",\"label\":\"李老师\"}],\"answer\":\"c3\",\"feedback\":\"李老师的名片 là danh thiếp của thầy/cô Lý. 的 thể hiện quan hệ sở hữu.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='7597944b-9946-4e42-9a10-234a0065fd9d');

-- Bài 4. 你去哪儿 — Bạn đi đâu?
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT 'c69c392c-d641-4594-adf5-dc1d1ae7a82a','{\"enabled\":true,\"place_id\":\"park\",\"missions\":[{\"id\":\"destination\",\"title\":\"Đi học cùng bạn\",\"instruction\":\"Nghe rồi chạm vào đúng địa điểm trên bản đồ.\",\"speech\":\"我去学校。你也来吧！\",\"type\":\"map\",\"options\":[],\"answer\":\"school\",\"feedback\":\"学校 là trường học. Bạn ấy đang rủ con đến trường.\"},{\"id\":\"going-home\",\"title\":\"Tan học rồi!\",\"instruction\":\"Nghe rồi chạm vào đúng địa điểm trên bản đồ.\",\"speech\":\"我现在回家。\",\"type\":\"map\",\"options\":[],\"answer\":\"home\",\"feedback\":\"回家 nghĩa là về nhà. Con đã tìm đúng ngôi nhà trên phố.\"},{\"id\":\"where\",\"title\":\"Bạn đang ở đâu?\",\"instruction\":\"Nghe câu hỏi rồi chọn câu nói về vị trí.\",\"speech\":\"你在哪儿？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我叫小安。\"},{\"id\":\"c2\",\"label\":\"我在学校。\"},{\"id\":\"c3\",\"label\":\"我很好。\"}],\"answer\":\"c2\",\"feedback\":\"在哪儿？ hỏi “ở đâu?”. 我在学校。 nghĩa là “Mình ở trường”.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='c69c392c-d641-4594-adf5-dc1d1ae7a82a');

-- Bài 5. 你要吃什么 — Bạn muốn ăn gì?
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT '56c0a9c1-7c01-4f38-a03e-7070d88a16d6','{\"enabled\":true,\"place_id\":\"restaurant\",\"missions\":[{\"id\":\"noodles\",\"title\":\"Gọi món đầu tiên\",\"instruction\":\"Nghe khách gọi món và chọn đúng món ăn.\",\"speech\":\"我要吃面条。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"米饭\"},{\"id\":\"c2\",\"label\":\"包子\"},{\"id\":\"c3\",\"label\":\"面条\"}],\"answer\":\"c3\",\"feedback\":\"面条 là mì. Khách vừa nói muốn ăn mì.\"},{\"id\":\"drink\",\"title\":\"Một món đồ uống\",\"instruction\":\"Nghe rồi chọn đúng đồ uống khách muốn.\",\"speech\":\"我不喝茶，我要喝咖啡。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"咖啡\"},{\"id\":\"c2\",\"label\":\"茶\"},{\"id\":\"c3\",\"label\":\"水\"}],\"answer\":\"c1\",\"feedback\":\"Khách không uống trà (不喝茶), muốn uống cà phê (要喝咖啡).\"},{\"id\":\"menu\",\"title\":\"Đến lượt con gọi món\",\"instruction\":\"Nghe người bán hỏi rồi chọn câu trả lời về món ăn.\",\"speech\":\"你要吃什么？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我是老师。\"},{\"id\":\"c2\",\"label\":\"我要吃米饭。\"},{\"id\":\"c3\",\"label\":\"我去学校。\"}],\"answer\":\"c2\",\"feedback\":\"你要吃什么？ hỏi muốn ăn gì. 我要吃米饭。 nghĩa là “Mình muốn ăn cơm”.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='56c0a9c1-7c01-4f38-a03e-7070d88a16d6');

-- Bài 6. 你在哪儿工作 — Bạn làm việc ở đâu?
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT '1da89e01-62d5-47a6-9e13-d6da5236f9a6','{\"enabled\":true,\"place_id\":\"office\",\"missions\":[{\"id\":\"job\",\"title\":\"Đoán nghề nghiệp\",\"instruction\":\"Nghe lời giới thiệu rồi chọn đúng nghề.\",\"speech\":\"我在学校工作，我是老师。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"医生\"},{\"id\":\"c2\",\"label\":\"学生\"},{\"id\":\"c3\",\"label\":\"老师\"}],\"answer\":\"c3\",\"feedback\":\"Bạn ấy làm việc ở trường và nói 我是老师。: “Mình là giáo viên”.\"},{\"id\":\"workplace\",\"title\":\"Tìm nơi làm việc\",\"instruction\":\"Nghe rồi chạm vào đúng địa điểm trên bản đồ.\",\"speech\":\"我在中国银行工作。\",\"type\":\"map\",\"options\":[],\"answer\":\"bank\",\"feedback\":\"中国银行 là Ngân hàng Trung Quốc. Bạn ấy làm việc ở ngân hàng.\"},{\"id\":\"work\",\"title\":\"Làm việc ở đâu?\",\"instruction\":\"Nghe câu hỏi rồi chọn câu trả lời về nơi làm việc.\",\"speech\":\"你在哪儿工作？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我在公司工作。\"},{\"id\":\"c2\",\"label\":\"我姓王。\"},{\"id\":\"c3\",\"label\":\"我喜欢喝茶。\"}],\"answer\":\"c1\",\"feedback\":\"我在公司工作。 nghĩa là “Mình làm việc ở công ty”. 公司 là công ty.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='1da89e01-62d5-47a6-9e13-d6da5236f9a6');

-- Bài 7. 中国银行在哪儿 — Ngân hàng Trung Quốc ở đâu?
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT '6481f2c3-2918-4c27-a80e-42d0a74f1b08','{\"enabled\":true,\"place_id\":\"bank\",\"missions\":[{\"id\":\"bank-right\",\"title\":\"Ngân hàng ở bên nào?\",\"instruction\":\"Nghe rồi chạm vào đúng địa điểm trên bản đồ.\",\"speech\":\"中国银行在饭馆的右边。请找一找。\",\"type\":\"map\",\"options\":[],\"answer\":\"bank\",\"feedback\":\"中国银行在饭馆的右边。: Ngân hàng Trung Quốc ở bên phải nhà hàng. Trên bản đồ, hai nơi nằm cùng một hàng.\"},{\"id\":\"office-left\",\"title\":\"Đi theo lời chỉ dẫn\",\"instruction\":\"Nghe rồi chạm vào đúng địa điểm trên bản đồ.\",\"speech\":\"公司在蛋糕店的左边。\",\"type\":\"map\",\"options\":[],\"answer\":\"office\",\"feedback\":\"公司在蛋糕店的左边。: Công ty ở bên trái tiệm bánh. 左边 nghĩa là bên trái.\"},{\"id\":\"home-right\",\"title\":\"Tìm nhà của bạn\",\"instruction\":\"Nghe rồi chạm vào đúng địa điểm trên bản đồ.\",\"speech\":\"我家在电影院的右边。\",\"type\":\"map\",\"options\":[],\"answer\":\"home\",\"feedback\":\"我家在电影院的右边。: Nhà mình ở bên phải rạp phim. 右边 nghĩa là bên phải.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='6481f2c3-2918-4c27-a80e-42d0a74f1b08');

-- Bài 8. 你的生日是几月几号 — Sinh nhật của bạn là ngày mấy tháng mấy?
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT 'ef30bc67-098c-4164-9914-3c6a3b7e3e9c','{\"enabled\":true,\"place_id\":\"bakery\",\"missions\":[{\"id\":\"birthday\",\"title\":\"Chọn đúng ngày sinh\",\"instruction\":\"Nghe rồi chọn ngày sinh nhật của bạn.\",\"speech\":\"我的生日是三月五号。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"五月三号\"},{\"id\":\"c2\",\"label\":\"三月五号\"},{\"id\":\"c3\",\"label\":\"三月十五号\"}],\"answer\":\"c2\",\"feedback\":\"三月五号 là ngày 5 tháng 3. 月 chỉ tháng, 号 chỉ ngày.\"},{\"id\":\"weekend\",\"title\":\"Lịch hẹn cuối tuần\",\"instruction\":\"Nghe câu hỏi và chọn ngày đúng.\",\"speech\":\"今天是星期六，明天是星期几？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"星期日\"},{\"id\":\"c2\",\"label\":\"星期五\"},{\"id\":\"c3\",\"label\":\"星期六\"}],\"answer\":\"c1\",\"feedback\":\"Hôm nay là thứ Bảy (星期六), ngày mai là Chủ nhật (星期日).\"},{\"id\":\"party\",\"title\":\"Lời mời sinh nhật\",\"instruction\":\"Nghe rồi chọn lời chúc phù hợp.\",\"speech\":\"今天是我的生日。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"早上好！\"},{\"id\":\"c2\",\"label\":\"再见！\"},{\"id\":\"c3\",\"label\":\"生日快乐！\"}],\"answer\":\"c3\",\"feedback\":\"生日快乐！ nghĩa là “Chúc mừng sinh nhật!”.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='ef30bc67-098c-4164-9914-3c6a3b7e3e9c');

-- Bài 9. 你喜欢中国电影还是美国电影 — Bạn thích phim Trung Quốc hay phim Mỹ?
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT 'c16938ad-72fb-4610-b053-85d0ba339637','{\"enabled\":true,\"place_id\":\"cinema\",\"missions\":[{\"id\":\"movie\",\"title\":\"Chọn một bộ phim\",\"instruction\":\"Nghe câu hỏi rồi chọn câu trả lời nói về sở thích phim.\",\"speech\":\"你喜欢中国电影还是美国电影？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我在银行工作。\"},{\"id\":\"c2\",\"label\":\"我喜欢中国电影。\"},{\"id\":\"c3\",\"label\":\"我家有三口人。\"}],\"answer\":\"c2\",\"feedback\":\"还是 nối các lựa chọn trong câu hỏi. 我喜欢中国电影。: “Mình thích phim Trung Quốc”.\"},{\"id\":\"preference\",\"title\":\"Sở thích của bạn\",\"instruction\":\"Nghe rồi chọn điều bạn ấy thích.\",\"speech\":\"我不喜欢喝茶，我喜欢喝咖啡。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"咖啡\"},{\"id\":\"c2\",\"label\":\"茶\"},{\"id\":\"c3\",\"label\":\"水\"}],\"answer\":\"c1\",\"feedback\":\"Bạn ấy thích uống cà phê (喜欢喝咖啡), không thích uống trà (不喜欢喝茶).\"},{\"id\":\"invitation\",\"title\":\"Hẹn đi xem phim\",\"instruction\":\"Nghe lời rủ rồi chọn câu đồng ý.\",\"speech\":\"我们星期天去看电影，好吗？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我是越南人。\"},{\"id\":\"c2\",\"label\":\"我家有四口人。\"},{\"id\":\"c3\",\"label\":\"好啊！\"}],\"answer\":\"c3\",\"feedback\":\"好啊！ là lời đồng ý “Được chứ!”. 去看电影 nghĩa là đi xem phim.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='c16938ad-72fb-4610-b053-85d0ba339637');

-- Bài 10. 你家有几口人 — Gia đình bạn có mấy người?
INSERT INTO chinese_street_lessons(lesson_id,data,revision)
SELECT 'f6921a03-78ee-41d1-8450-086835287983','{\"enabled\":true,\"place_id\":\"home\",\"missions\":[{\"id\":\"family-count\",\"title\":\"Nhà có mấy người?\",\"instruction\":\"Nghe lời giới thiệu rồi chọn số người trong gia đình.\",\"speech\":\"我家有四口人：爸爸、妈妈、姐姐和我。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"三口人\"},{\"id\":\"c2\",\"label\":\"五口人\"},{\"id\":\"c3\",\"label\":\"四口人\"}],\"answer\":\"c3\",\"feedback\":\"Gia đình có bố, mẹ, chị gái và bạn ấy: 四口人, bốn người.\"},{\"id\":\"younger-brother\",\"title\":\"Em trai của ai?\",\"instruction\":\"Nghe rồi nhận biết thành viên gia đình.\",\"speech\":\"这是我弟弟，他是学生。\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"弟弟\"},{\"id\":\"c2\",\"label\":\"哥哥\"},{\"id\":\"c3\",\"label\":\"爸爸\"}],\"answer\":\"c1\",\"feedback\":\"弟弟 là em trai; 哥哥 là anh trai; 爸爸 là bố.\"},{\"id\":\"family-question\",\"title\":\"Kể về gia đình\",\"instruction\":\"Nghe câu hỏi rồi chọn câu trả lời đúng ý.\",\"speech\":\"你家有几口人？\",\"type\":\"choice\",\"options\":[{\"id\":\"c1\",\"label\":\"我喜欢中国电影。\"},{\"id\":\"c2\",\"label\":\"我家有三口人。\"},{\"id\":\"c3\",\"label\":\"我在公司工作。\"}],\"answer\":\"c2\",\"feedback\":\"你家有几口人？ hỏi gia đình có mấy người. 我家有三口人。: “Nhà mình có ba người”.\"}]}',1
WHERE NOT EXISTS (SELECT 1 FROM chinese_street_lessons WHERE lesson_id='f6921a03-78ee-41d1-8450-086835287983');
COMMIT;
